package com.bank.benchmark.service;

import java.util.List;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Finds the Kth smallest fee across M sorted lists via early-stopped K-way merge.
public class FeeBenchmarkService {
    private static final Logger log = Logger.getLogger(FeeBenchmarkService.class.getName());

    public int kthSmallest(List<List<Integer>> lists, int k) {
        // Heap entry: {value, listIndex, elementIndex}; ordered by value.
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
        for (int i = 0; i < lists.size(); i++) {
            if (!lists.get(i).isEmpty()) {
                pq.add(new int[]{lists.get(i).get(0), i, 0});   // seed first of each list
            }
        }
        int result = -1;
        for (int count = 0; count < k && !pq.isEmpty(); count++) {
            int[] top = pq.poll();                              // current global minimum
            result = top[0];
            int li = top[1], ei = top[2];
            if (ei + 1 < lists.get(li).size()) {
                pq.add(new int[]{lists.get(li).get(ei + 1), li, ei + 1});  // successor
            }
        }
        final int ans = result;
        log.info(() -> "Kth smallest (k=" + k + ") = " + ans);
        return result;
    }
}
