package com.bank.benchmark;

import com.bank.benchmark.service.FeeBenchmarkService;
import java.util.List;
import java.util.logging.Logger;

public class FeeBenchmarkApplication {
    private static final Logger log = Logger.getLogger(FeeBenchmarkApplication.class.getName());

    public static void main(String[] args) {
        FeeBenchmarkService service = new FeeBenchmarkService();
        List<List<Integer>> lists = List.of(
            List.of(20, 60, 90),      // branch 1 sorted fees
            List.of(50, 70, 80),      // branch 2 sorted fees
            List.of(10, 40)           // branch 3 sorted fees
        );
        int k = 4;
        int kth = service.kthSmallest(lists, k);
        log.info("The " + k + "th smallest fee is Rs." + kth);
    }
}
